-- Production-safe dry run for the 70-product Biorona catalog.
-- This transaction always rolls back.
begin;

do $validation$
declare
  bad_categories text;
begin
  select string_agg(required_name, ', ' order by required_name)
    into bad_categories
  from unnest(ARRAY['Buket Fresh Flower', 'Buket Artificial', 'Standing Flower', 'Bloom Box', 'Anggrek dalam Vase', 'Custom Arrangement / Vase', 'Bunga Papan / Ucapan', 'Hampers & Gift']::text[]) required_name
  where not exists (
    select 1
    from public.categories c
    where lower(btrim(c.name)) = lower(btrim(required_name))
      and c.is_active = true
  );

  if bad_categories is not null then
    raise exception 'Kategori tidak ditemukan atau tidak aktif: %', bad_categories;
  end if;
end
$validation$;

