),
dataset_check as (
  select
    case when count(*) = 70
      and count(distinct sku) = 70
      and count(distinct slug) = 70
      and bool_and(price > 0)
      and bool_and(cardinality(colors) > 0)
      and bool_and(cardinality(occasions) > 0)
      and bool_and(length(btrim(short_description)) > 0)
      and bool_and(length(btrim(description)) > 0)
      and bool_and(length(btrim(seo_description)) > 0)
    then 1 else 0 end as valid
  from candidates
),
resolved as (
  select c.*, cat.id as category_id
  from candidates c
  join public.categories cat
    on lower(btrim(cat.name)) = lower(btrim(c.category_name))
   and cat.is_active = true
  cross join dataset_check d
  where 1 / d.valid = 1
),
classified as (
  select r.*,
    exists (select 1 from public.products p where p.sku = r.sku) as sku_exists,
    exists (select 1 from public.products p where p.slug = r.slug) as slug_exists
  from resolved r
)
select
  (select count(*) from candidates) as candidate_count,
  count(*) filter (where not sku_exists and not slug_exists) as will_insert_count,
  count(*) filter (where sku_exists) as skipped_sku_existing_count,
  count(*) filter (where slug_exists) as skipped_slug_existing_count,
  (select sum(price) from candidates) as candidate_total_price,
  jsonb_object_agg(category_name, category_count order by category_name) as candidate_count_by_category,
  array_agg(sku order by sku) filter (where not sku_exists and not slug_exists) as skus_to_insert
from classified
join (
  select category_name, count(*) as category_count
  from candidates
  group by category_name
) category_totals using (category_name);

rollback;
